def _disc(level):
    up = level.upper()
    en_r, fr_r, de_r, es_r = _REGION[level[0]]
    ex = _EXTRA.get(level, ("", "", "", ""))
    sp = lambda s: (" " + s) if s else ""
    return (f"intervertebral disc {level}",
            f"Intervertebral disc {up}", f"Fibrocartilaginous disc between the {up} vertebral bodies ({en_r} region); an outer annulus fibrosus surrounds the inner nucleus pulposus, spreading load and allowing movement." + sp(ex[0]),
            f"Disque intervertébral {up}", f"Disque fibrocartilagineux entre les corps vertébraux {up} (région {fr_r}) ; l'anneau fibreux externe entoure le noyau pulpeux, répartit les charges et permet le mouvement." + sp(ex[1]),
            f"Bandscheibe {up}", f"Faserknorpelscheibe zwischen den Wirbelkörpern {up} ({de_r}); außen Anulus fibrosus, innen Nucleus pulposus; verteilt die Last und ermöglicht Bewegung." + sp(ex[2]),
            f"Disco intervertebral {up}", f"Disco fibrocartilaginoso entre los cuerpos vertebrales {up} (región {es_r}); el anillo fibroso externo rodea el núcleo pulposo, reparte la carga y permite el movimiento." + sp(ex[3]))


